/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: PagePlacement, OrderItem, OrderReview, PageOrderReview
 *   Functions: changedPositions, PageOrderSummary, PageOrderNotice, PageOrderApproval, SortableOrderList,
 *              PageOrderList
 * Internal
 *   Types: OrderPresentation
 * @end-catalog */

import { useEffect, useId, useRef, useState, type DragEvent, type ReactNode } from 'react';
import { ArrowDown, ArrowUp, GripVertical } from 'lucide-react';
import type { AdminPage } from './catalogApi';
import type { useAdminPageText } from './adminPageText';
import { ModalDialog, type ModalDialogProps } from '../../components/ModalDialog';

export type PagePlacement = AdminPage['items'][number];
/** Shared sortable identity; presentation and domain metadata remain with each editor. */
export interface OrderItem { itemId: string; name: string | null; visibility?: 'public' | 'hidden' }
export interface OrderReview<Item extends OrderItem> { items: Item[]; originalIds: string[]; revision: string }
/** A local order and its captured revision remain independent of refreshed server state. */
export type PageOrderReview = OrderReview<PagePlacement>;
/** The lazy editor receives the existing Page presentation without importing its route bundle. */
interface OrderPresentation<Item extends OrderItem = PagePlacement> {
  text: ReturnType<typeof useAdminPageText>; styles: Record<string, string>;
  renderIcon: (item: Item, size: number) => ReactNode;
}

/** Counts displaced rows too, and treats returning to the original order as an unchanged draft. */
export const changedPositions = (review: PageOrderReview) => review.items.filter((item, index) => review.originalIds[index] !== item.itemId).length;

/** Complete, frozen order used in both approval and uncertain-operation recovery. */
export function PageOrderSummary({ review, label, text: t, styles, renderIcon }: OrderPresentation & { review: PageOrderReview; label: string }) {
  return <ol className={styles.orderSummary} aria-label={label}>{review.items.map((item, index) => {
    const original = review.originalIds.indexOf(item.itemId);
    return <li key={item.itemId}>
      <span className={styles.position}>{String(index + 1).padStart(2, '0')}</span>{renderIcon(item, 18)}
      <span className={styles.summaryName}>{item.name || t('catalog.placement_name_missing')}</span>
      {original !== index && <span className={styles.originalPosition}>{t('pages.order_original', { position: original + 1 })}</span>}
    </li>;
  })}</ol>;
}

/** Recovery compares a frozen approved order with the independently refreshed list below it. */
export function PageOrderNotice({ review, unknown, error, page, actions, ...presentation }: OrderPresentation & {
  review: PageOrderReview; unknown: boolean; error: string; page: string; actions: ReactNode;
}) {
  const { text: t, styles } = presentation;
  return <div className={styles.notice} role="alert"><div>
    <p className={styles.noticeTitle}>{t(unknown ? 'pages.order_unknown' : 'pages.order_failed', { page })}</p>
    <p>{t(unknown ? 'pages.order_unknown_copy' : error === 'conflict' ? 'pages.order_conflict' : error === 'order_identity' ? 'pages.order_identity' : error === 'order_capacity' ? 'pages.order_capacity' : 'pages.order_error')}</p>
    {unknown && <details className={styles.originalOrder}><summary>{t('pages.order_view_original')}</summary><PageOrderSummary {...presentation} review={review} label={t('pages.order_original_list')} /></details>}
  </div><div className={styles.noticeActions}>{actions}</div></div>;
}

/** Approval controls mount together with the complete readable order, never ahead of lazy content. */
export function PageOrderApproval({ review, page, stale, actions, initialFocusRef, returnFocusRef, onClose, closeDisabled, ...presentation }: OrderPresentation & {
  review: PageOrderReview; page: string; stale: boolean; actions: ReactNode;
} & Pick<ModalDialogProps, 'initialFocusRef' | 'returnFocusRef' | 'onClose' | 'closeDisabled'>) {
  const { text: t, styles } = presentation;
  return <ModalDialog title={t('pages.order_confirm_title')} description={t('pages.order_confirm_copy')}
    initialFocusRef={initialFocusRef} returnFocusRef={returnFocusRef} onClose={onClose} closeDisabled={closeDisabled}>
    <p className={styles.targetPage}>{page} · {t('pages.order_changed', { count: changedPositions(review) })}</p>
    <PageOrderSummary {...presentation} review={review} label={t('pages.order_new')} />
    <p className={styles.definitionScope}>{t('pages.order_scope')}</p>
    {stale && <p className={styles.notice} role="alert">{t('pages.order_stale')}</p>}
    <div className={styles.dialogActions}>{actions}</div>
  </ModalDialog>;
}

/** Native drag uses a floating row image and one empty slot; arrows offer the same local edit without dragging. */
export function SortableOrderList<Item extends OrderItem>({ review, disabled, onChange, onDragging, text: t, styles, renderIcon, renderVisibility, renderMetadata }: OrderPresentation<Item> & {
  review: OrderReview<Item>; disabled: boolean; onChange: (items: Item[]) => void; onDragging: (value: boolean) => void;
  renderMetadata: (item: Item) => ReactNode; renderVisibility: (item: Item) => ReactNode;
}) {
  const hint = useId();
  const [dragged, setDragged] = useState<string | null>(null), [announcement, setAnnouncement] = useState('');
  const drag = useRef<{ id: string; before: Item[]; dropped: boolean } | null>(null);
  const dragImage = useRef<HTMLElement | null>(null);
  useEffect(() => () => dragImage.current?.remove(), []);
  useEffect(() => { handles.current.get(review.items[0]?.itemId)?.focus(); }, []);
  const handles = useRef(new Map<string, HTMLButtonElement>());
  /** Moves the same identity, keeping focus and announcements attached to that item after reflow. */
  function move(id: string, to: number, focus = true) {
    if (disabled) return;
    const from = review.items.findIndex(item => item.itemId === id);
    if (from < 0 || to < 0 || to >= review.items.length || from === to) return;
    const items = [...review.items], [item] = items.splice(from, 1); items.splice(to, 0, item);
    onChange(items);
    setAnnouncement(t('pages.order_moved', { name: item.name || t('catalog.placement_name_missing'), position: to + 1, count: items.length }));
    if (focus) handles.current.get(id)?.focus();
  }
  function dragOver(event: DragEvent<HTMLLIElement>, index: number) {
    if (!drag.current || disabled) return;
    event.preventDefault(); event.dataTransfer.dropEffect = 'move';
    const from = review.items.findIndex(item => item.itemId === drag.current!.id);
    const rect = event.currentTarget.getBoundingClientRect(), lower = event.clientY >= rect.top + rect.height / 2;
    if (index < from && !lower || index > from && lower) move(drag.current.id, index, false);
  }
  function finishDrag() {
    const active = drag.current;
    if (active && !active.dropped) onChange(active.before);
    dragImage.current?.remove(); dragImage.current = null;
    drag.current = null; setDragged(null); onDragging(false);
  }
  return <>
    <span id={hint} className={styles.srOnly}>{t('pages.order_keyboard')}</span>
    <p role="status" aria-live="polite" className={styles.srOnly}>{announcement}</p>
    <ol className={styles.list} aria-label={t('pages.order_draft')} onDragOver={event => { if (drag.current) event.preventDefault(); }}
      onDrop={event => { if (drag.current) { event.preventDefault(); drag.current.dropped = true; finishDrag(); } }}>
      {review.items.map((item, index) => {
        const name = item.name || t('catalog.placement_name_missing');
        const original = review.originalIds.indexOf(item.itemId), hidden = item.visibility === 'hidden';
        return <li key={item.itemId} data-item-id={item.itemId} onDragOver={event => dragOver(event, index)}
          className={`${styles.placement} ${styles.sortable} ${hidden ? styles.hidden : ''} ${dragged === item.itemId ? styles.dragSlot : ''}`}>
          <button type="button" className={styles.dragHandle} ref={element => { if (element) handles.current.set(item.itemId, element); else handles.current.delete(item.itemId); }}
            aria-label={t('pages.order_handle', { name })} aria-describedby={hint} title={t('pages.order_keyboard')} disabled={disabled} draggable={!disabled}
            onKeyDown={event => { if (['ArrowUp', 'ArrowDown'].includes(event.key)) { event.preventDefault(); move(item.itemId, index + (event.key === 'ArrowUp' ? -1 : 1)); } }}
            onDragStart={event => {
              if (disabled) { event.preventDefault(); return; }
              event.dataTransfer.effectAllowed = 'move'; event.dataTransfer.setData('text/plain', item.itemId);
              const row = event.currentTarget.closest('li')!, rect = row.getBoundingClientRect();
              // A separate image stays visible when React turns the moving row into an empty slot.
              const image = row.cloneNode(true) as HTMLElement;
              image.setAttribute('aria-hidden', 'true'); image.inert = true;
              Object.assign(image.style, { position: 'fixed', left: '-10000px', top: '0', width: rect.width + 'px', listStyle: 'none', background: 'var(--color-surface-raised)', border: '1px solid var(--color-border-strong)', boxShadow: '0 10px 30px #0006' });
              dragImage.current?.remove(); dragImage.current = image; document.body.appendChild(image);
              event.dataTransfer.setDragImage(image, event.clientX - rect.left, event.clientY - rect.top);
              drag.current = { id: item.itemId, before: [...review.items], dropped: false };
              setDragged(item.itemId); onDragging(true);
            }} onDragEnd={finishDrag}><GripVertical size={20} aria-hidden /></button>
          <span className={styles.position} aria-hidden>{String(index + 1).padStart(2, '0')}</span>
          <span className={styles.typeIcon}>{renderIcon(item, 23)}</span>
          <div className={styles.identity}><h3 aria-label={`${index + 1} · ${name}`} className={!item.name ? styles.unnamed : undefined}>{name}</h3>
            {renderMetadata(item)}
            {original !== index && <span className={styles.originalPosition}>{t('pages.order_original', { position: original + 1 })}</span>}
          </div>
          {renderVisibility(item)}
          <div className={styles.moveActions}>
            <button type="button" className={styles.moveButton} aria-label={t('pages.order_up', { name })} title={t('pages.order_up', { name })} disabled={disabled || index === 0}
              onClick={() => move(item.itemId, index - 1)}><ArrowUp size={18} aria-hidden /><span>{t('pages.order_up_short')}</span></button>
            <button type="button" className={styles.moveButton} aria-label={t('pages.order_down', { name })} title={t('pages.order_down', { name })} disabled={disabled || index === review.items.length - 1}
              onClick={() => move(item.itemId, index + 1)}><ArrowDown size={18} aria-hidden /><span>{t('pages.order_down_short')}</span></button>
          </div>
        </li>;
      })}
    </ol>
  </>;
}

/** Keeps the page-placement editor's lazy interface concrete while sharing its accessible sorting mechanics. */
export function PageOrderList(props: OrderPresentation & {
  review: PageOrderReview; disabled: boolean; onChange: (items: PagePlacement[]) => void; onDragging: (value: boolean) => void;
  renderMetadata: (item: PagePlacement) => ReactNode; renderVisibility: (item: PagePlacement) => ReactNode;
}) {
  return <SortableOrderList {...props} />;
}
